import type { HandbookDocumentContent } from "../types";

const document: HandbookDocumentContent = {
  navHtml: "<div class=\"nav-brand\">ENGINEERING · FRONTEND QUALITY</div>\n  <div class=\"nav-title\">프론트엔드 품질 · 보안 테스트 배포</div>\n  <a href=\"#bundle-index\"><span class=\"code\">INDEX</span>통합 문서</a>\n  <a href=\"#frontend-release-quality-model\"><span class=\"code\">MODEL</span>릴리스 품질 모델</a>\n  <a href=\"#frontend-quality-output\"><span class=\"code\">OUTPUT</span>품질 산출물</a>\n  <a href=\"#doc-fesec\"><span class=\"code\">DOC</span>보안 대응</a>\n  <a href=\"#doc-fetest\"><span class=\"code\">DOC</span>테스트 전략</a>\n  <a href=\"#doc-fedeploy\"><span class=\"code\">DOC</span>배포</a>\n  <a href=\"#doc-fesec\"><span class=\"code\">SRC</span>보안 대응</a>\n<a href=\"#fesec-ch1\"><span class=\"code\">FSEC-01</span>브라우저 위협 모델</a>\n  <a href=\"#fesec-ch2\"><span class=\"code\">FSEC-02</span>XSS와 HTML 주입</a>\n  <a href=\"#fesec-ch3\"><span class=\"code\">FSEC-03</span>CSRF와 쿠키</a>\n  <a href=\"#fesec-ch4\"><span class=\"code\">FSEC-04</span>토큰 저장</a>\n  <a href=\"#fesec-ch5\"><span class=\"code\">FSEC-05</span>CSP와 보안 헤더</a>\n  <a href=\"#fesec-ch6\"><span class=\"code\">FSEC-06</span>의존성과 공급망</a>\n  <a href=\"#fesec-ch7\"><span class=\"code\">FSEC-07</span>보안 방법론</a>\n  <a href=\"#doc-fetest\"><span class=\"code\">SRC</span>테스트 전략</a>\n<a href=\"#fetest-ch1\"><span class=\"code\">FTEST-01</span>테스트의 목적</a>\n  <a href=\"#fetest-ch2\"><span class=\"code\">FTEST-02</span>테스트 피라미드</a>\n  <a href=\"#fetest-ch3\"><span class=\"code\">FTEST-03</span>컴포넌트 테스트</a>\n  <a href=\"#fetest-ch4\"><span class=\"code\">FTEST-04</span>E2E 테스트</a>\n  <a href=\"#fetest-ch5\"><span class=\"code\">FTEST-05</span>Mock 전략</a>\n  <a href=\"#fetest-ch6\"><span class=\"code\">FTEST-06</span>시각 회귀</a>\n  <a href=\"#fetest-ch7\"><span class=\"code\">FTEST-07</span>테스트 방법론</a>\n  <a href=\"#doc-fedeploy\"><span class=\"code\">SRC</span>배포</a>\n<a href=\"#fedeploy-ch1\"><span class=\"code\">DEP-01</span>프론트엔드 배포의 본질</a>\n  <a href=\"#fedeploy-ch2\"><span class=\"code\">DEP-02</span>Vite build와 환경변수</a>\n  <a href=\"#fedeploy-ch3\"><span class=\"code\">DEP-03</span>정적 호스팅·CDN·캐시</a>\n  <a href=\"#fedeploy-ch4\"><span class=\"code\">DEP-04</span>sourcemap과 오류 수집</a>\n  <a href=\"#fedeploy-ch5\"><span class=\"code\">DEP-05</span>rollback과 release</a>\n  <a href=\"#fedeploy-ch6\"><span class=\"code\">DEP-06</span>배포 체크리스트</a>\n  <a href=\"#fedeploy-ch7\"><span class=\"code\">DEP-07</span>릴리스 증거와 피드백 루프</a>",
  mainHtml: "<header class=\"hero\">\n  <div class=\"hero-serial\">\n    <span>DOC : ENGINEERING-FRONTEND-QUALITY</span>\n    <span>SCOPE : SECURITY · TESTING · DEPLOYMENT</span>\n    <span>LANG : KO</span>\n  </div>\n  <h1>프론트엔드 품질과 릴리스</h1>\n  <p class=\"hero-sub\">프론트엔드 보안, 테스트 전략, 배포 문서를 운영 품질 기준으로 통합했습니다.</p>\n  <div class=\"hero-meta\">CURATED HANDBOOK PATH · SOURCES : 3 DOCUMENTS · UPDATED 2026-06</div>\n</header>\n\n<section id=\"bundle-index\">\n<div class=\"ch-head\"><span class=\"ch-code\">INDEX</span><h2>통합 문서</h2></div>\n<p class=\"lede\">프론트엔드 품질·릴리스는 보안, 테스트, 배포를 따로 점검하는 목록이 아니라 변경을 안전하게 사용자에게 내보내는 운영 루프입니다. 변경 위험을 분류하고, 그 위험에 맞는 테스트와 보안 리뷰를 선택하고, preview와 CI에서 확인한 뒤, release health window 동안 오류·Web Vitals·API 실패율을 관찰하고 rollback 또는 forward fix를 결정합니다.</p>\n<ul><li>보안 대응</li><li>테스트 전략</li><li>배포</li></ul>\n<p class=\"dim\">통합 원문: FRONTEND SECURITY HANDBOOK · FRONTEND TESTING HANDBOOK · FRONTEND DEPLOYMENT HANDBOOK</p>\n</section>\n\n<section id=\"frontend-release-quality-model\">\n<div class=\"ch-head\"><span class=\"ch-code\">MODEL</span><h2>FRONTEND RELEASE QUALITY OPERATING MODEL</h2></div>\n<p class=\"lede\">프론트엔드 품질은 테스트 개수나 배포 성공 로그가 아니라 사용자의 브라우저에서 새 버전이 안전하게 작동한다는 증거입니다. 이 모델은 변경이 들어온 순간부터 release health window가 끝날 때까지의 판단 순서를 고정합니다.</p>\n<div class=\"semantic-card model\">\n<span class=\"sc-label\">FRONTEND RELEASE QUALITY OPERATING MODEL</span>\n1 change risk classification → 2 security review gate → 3 risk based test matrix<br>\n→ 4 preview deployment → 5 CI quality gate → 6 release notes<br>\n→ 7 canary or staged rollout → 8 release health window<br>\n→ 9 Web Vitals regression / error spike / API failure review<br>\n→ 10 rollback, feature flag kill switch, or forward fix decision\n</div>\n<div class=\"glossary\">\n<div class=\"g-row\"><div class=\"g-term\"><b>1 · 변경 위험 분류</b><span>change risk classification</span></div><div class=\"g-def\">이 변경이 깨지면 무엇을 잃는지로 등급을 나눈다. 뒤의 게이트 강도가 여기서 정해진다</div></div>\n<div class=\"g-row\"><div class=\"g-term\"><b>2 · 보안 리뷰 게이트</b><span>security review gate</span></div><div class=\"g-def\">입력 처리, 인증, 서드파티, 권한이 걸린 변경인지 먼저 거른다</div></div>\n<div class=\"g-row\"><div class=\"g-term\"><b>3 · 위험 기반 테스트 행렬</b><span>risk based test matrix</span></div><div class=\"g-def\">위험마다 가장 싸고 안정적인 테스트 층을 배정한다. 모든 변경에 같은 테스트를 요구하지 않는다</div></div>\n<div class=\"g-row\"><div class=\"g-term\"><b>4 · 프리뷰 배포</b><span>preview deployment</span></div><div class=\"g-def\">머지 전에 실제 URL로 확인한다. 스크린샷 대신 만져볼 수 있는 것을 리뷰에 붙인다</div></div>\n<div class=\"g-row\"><div class=\"g-term\"><b>5 · CI 품질 게이트</b><span>CI quality gate</span></div><div class=\"g-def\">타입, 린트, 테스트, 번들 예산을 자동으로 막는다. 사람이 기억해야 하는 규칙은 지켜지지 않는다</div></div>\n<div class=\"g-row\"><div class=\"g-term\"><b>6 · 릴리스 노트</b><span>release notes</span></div><div class=\"g-def\">무엇이 바뀌고 무엇이 위험한지 남긴다. 장애 때 가장 먼저 열리는 문서다</div></div>\n<div class=\"g-row\"><div class=\"g-term\"><b>7 · 카나리·단계 배포</b><span>canary or staged rollout</span></div><div class=\"g-def\">일부 트래픽에 먼저 낸다. 전량 배포는 되돌릴 비용이 가장 큰 선택이다</div></div>\n<div class=\"g-row\"><div class=\"g-term\"><b>8 · 릴리스 관찰 창</b><span>release health window</span></div><div class=\"g-def\">배포 후 지켜보는 시간. 이 창이 없으면 배포는 끝난 것이 아니라 방치된 것이다</div></div>\n<div class=\"g-row\"><div class=\"g-term\"><b>9 · 회귀 검토</b><span>Web Vitals / error / API review</span></div><div class=\"g-def\">성능 지표, 오류 급증, API 실패를 배포 전후로 비교한다</div></div>\n<div class=\"g-row\"><div class=\"g-term\"><b>10 · 복구 결정</b><span>rollback / kill switch / forward fix</span></div><div class=\"g-def\">되돌릴지, 기능만 끌지, 고쳐서 나갈지. 셋 중 무엇을 쓸지 배포 전에 정해 둔다</div></div>\n</div>\n<table>\n<tr><th>단계</th><th>품질 질문</th><th>통과 증거</th></tr>\n<tr><td>change risk classification</td><td>이 변경이 보안, 데이터, 권한, 라우팅, 성능, 공통 UI 중 무엇을 건드리는가</td><td>PR risk label, 영향 route, owner, rollback path</td></tr>\n<tr><td>테스트 선택</td><td>unit/component/E2E/visual/a11y/contract 중 무엇이 이 위험을 막는가</td><td>RISK BASED TEST MATRIX와 실행 결과</td></tr>\n<tr><td>보안 게이트</td><td>토큰, HTML, redirect, third-party script, CSP, dependency가 바뀌었는가</td><td>security review note, sanitizer regression, CSP report</td></tr>\n<tr><td>배포 검증</td><td>preview에서 실제 빌드 산출물, cache header, route fallback, release id가 맞는가</td><td>preview smoke, artifact hash, sourcemap upload record</td></tr>\n<tr><td>릴리스 관찰</td><td>새 버전이 사용자 오류, Web Vitals, API 실패율을 악화시키는가</td><td>release health window dashboard와 rollback/forward fix decision</td></tr>\n</table>\n</section>\n\n<section id=\"frontend-quality-output\">\n<div class=\"ch-head\"><span class=\"ch-code\">OUTPUT</span><h2>FRONTEND QUALITY OUTPUTS</h2></div>\n<p class=\"lede\">이 문서를 읽은 뒤 남겨야 하는 것은 지식 요약이 아니라 릴리스 때 재사용할 수 있는 증거 패킷입니다.</p>\n<table>\n<tr><th>산출물</th><th>포함 내용</th><th>왜 필요한가</th></tr>\n<tr><td>release notes</td><td>변경 범위, 위험 분류, flag, migration/API dependency, rollback path</td><td>배포 후 판단 기준을 팀이 공유한다</td></tr>\n<tr><td>security review note</td><td>HTML/token/CSP/redirect/dependency 변경 여부와 통과 근거</td><td>보안 변경을 일반 UI 변경처럼 흘려보내지 않는다</td></tr>\n<tr><td>test evidence packet</td><td>unit, component, E2E, visual, a11y, contract 실행 결과</td><td>위험에 맞는 테스트를 선택했는지 증명한다</td></tr>\n<tr><td>release health record</td><td>error rate, chunk load error, Web Vitals regression, API failure, user report</td><td>배포 성공을 CI가 아니라 실제 사용자 지표로 닫는다</td></tr>\n<tr><td>incident packet</td><td>증상, 영향 route, release id, mitigation, owner, follow-up test</td><td>같은 릴리스 사고가 반복되지 않게 한다</td></tr>\n</table>\n</section>\n\n<section id=\"doc-fesec\">\n<div class=\"ch-head\"><span class=\"ch-code\">SOURCE</span><h2>보안 대응</h2></div>\n</section>\n\n<section id=\"fesec-ch1\">\n<div class=\"ch-head\"><span class=\"ch-code\">FSEC-01</span><h2>브라우저 위협 모델</h2></div>\n<p class=\"lede\">사용자 입력, URL parameter, 외부 API, CMS 콘텐츠, third-party script는 모두 신뢰할 수 없는 입력입니다.</p>\n<table>\n<tr><th>표면</th><th>위험</th><th>대응</th></tr>\n<tr><td>DOM 삽입</td><td>XSS</td><td>escape 기본값 유지, sanitize</td></tr>\n<tr><td>쿠키</td><td>CSRF, session fixation</td><td>SameSite, CSRF token, Secure, HttpOnly</td></tr>\n<tr><td>Storage</td><td>XSS 시 token 탈취</td><td>민감 정보 저장 최소화</td></tr>\n<tr><td>URL</td><td>open redirect, reflected XSS</td><td>allowlist, 상대 경로 제한</td></tr>\n<tr><td>Dependency</td><td>malicious package</td><td>lockfile, audit, 최소 의존성</td></tr>\n</table>\n<table>\n<tr><th>FRONTEND SECURITY RELEASE GATE</th><th>릴리스 차단 조건</th><th>통과 증거</th></tr>\n<tr><td>HTML 주입 표면</td><td><code>dangerouslySetInnerHTML</code>, markdown, CMS, rich text renderer가 바뀌었다</td><td>허용 tag/attribute 리뷰, sanitizer regression, XSS payload negative test</td></tr>\n<tr><td>토큰·세션</td><td>token storage, cookie option, refresh flow, logout/revoke가 바뀌었다</td><td>XSS/CSRF 위험 비교, SameSite/HttpOnly/Secure 확인, 세션 폐기 테스트</td></tr>\n<tr><td>redirect·URL</td><td>callback URL, deep link, 외부 이동, returnTo 파라미터가 바뀌었다</td><td>origin/domain allowlist, open redirect negative test, URL scheme 검증</td></tr>\n<tr><td>third-party script</td><td>analytics, 채팅, 결제, A/B test script가 추가되었다</td><td>CSP/SRI 검토, 로드 범위 제한, PII 전송 여부 확인</td></tr>\n<tr><td>dependency</td><td>lockfile 또는 install script가 바뀌었다</td><td>audit 결과, transitive diff, maintainer/reachability 판단, rollback 가능성</td></tr>\n</table>\n</section>\n\n<section id=\"fesec-ch2\">\n<div class=\"ch-head\"><span class=\"ch-code\">FSEC-02</span><h2>XSS와 HTML 주입</h2></div>\n<p class=\"lede\">XSS는 공격자가 브라우저에서 스크립트를 실행하게 만드는 취약점입니다. React는 문자열 escape를 기본 제공하지만, 그 안전장치를 끄면 책임은 개발자에게 넘어갑니다.</p>\n<table>\n<tr><th>패턴</th><th>위험</th><th>대응</th></tr>\n<tr><td><code>dangerouslySetInnerHTML</code></td><td>HTML 실행 표면</td><td>sanitize 후 제한된 곳에서만 사용</td></tr>\n<tr><td>markdown 렌더링</td><td>링크, HTML, script 주입</td><td>HTML 비활성화 또는 sanitizer</td></tr>\n<tr><td>URL 삽입</td><td><code>javascript:</code> scheme</td><td>protocol allowlist</td></tr>\n<tr><td>third-party script</td><td>공급망 XSS</td><td>SRI, CSP, 최소 로드</td></tr>\n</table>\n<table>\n<tr><th>React 실무 지점</th><th>기준</th></tr>\n<tr><td>외부 HTML/CMS/markdown</td><td>서버에서 왔어도 untrusted로 취급. raw HTML 비활성화 또는 DOMPurify 같은 검증된 sanitizer 사용</td></tr>\n<tr><td>링크</td><td><code>target=\"_blank\"</code>에는 <code>rel=\"noopener noreferrer\"</code>를 함께 사용</td></tr>\n<tr><td>URL/path/style 속성</td><td>사용자 입력을 직접 넣지 않고 protocol/domain/value allowlist 검증</td></tr>\n<tr><td>sanitizer 설정</td><td>허용 tag/attribute를 리뷰하고, 보안 변경으로 취급</td></tr>\n</table>\n<div class=\"callout risk\"><span class=\"co-label\">SANITIZE</span><p>escape와 sanitize는 다릅니다. escape는 문자열을 HTML로 실행되지 않게 바꾸고, sanitize는 허용된 HTML만 남깁니다. 사용자 생성 HTML이 필요하면 반드시 검증된 sanitizer를 사용합니다.</p></div>\n</section>\n\n<section id=\"fesec-ch3\">\n<div class=\"ch-head\"><span class=\"ch-code\">FSEC-03</span><h2>CSRF와 쿠키</h2></div>\n<p class=\"lede\">CSRF는 브라우저가 쿠키를 자동 첨부한다는 성질을 악용합니다. 사용자가 공격자 사이트를 방문했을 뿐인데 우리 서비스에 mutation 요청이 갈 수 있습니다.</p>\n<table>\n<tr><th>방어</th><th>설명</th><th>주의</th></tr>\n<tr><td>SameSite</td><td>cross-site 요청에 쿠키 첨부 제한</td><td>OAuth redirect와 호환성 확인</td></tr>\n<tr><td>CSRF token</td><td>공격자가 모르는 값을 mutation에 요구</td><td>token 전달/검증 경로 필요</td></tr>\n<tr><td>Origin/Referer 검증</td><td>요청 출처 확인</td><td>보조 방어로 사용</td></tr>\n<tr><td>재인증</td><td>위험 작업 전 추가 확인</td><td>UX 비용 있음</td></tr>\n</table>\n</section>\n\n<section id=\"fesec-ch4\">\n<div class=\"ch-head\"><span class=\"ch-code\">FSEC-04</span><h2>토큰 저장</h2></div>\n<p class=\"lede\">토큰 저장 위치에는 정답이 없습니다. XSS와 CSRF 중 어느 위험을 어떻게 줄일지의 선택입니다.</p>\n<table>\n<tr><th>위치</th><th>장점</th><th>위험</th></tr>\n<tr><td>memory</td><td>새로고침 시 사라져 탈취 창이 작음</td><td>새로고침 후 재인증/refresh 설계 필요</td></tr>\n<tr><td>localStorage</td><td>구현 쉬움</td><td>XSS가 읽을 수 있음</td></tr>\n<tr><td>HttpOnly cookie</td><td>JS가 읽을 수 없음</td><td>CSRF 방어 필요</td></tr>\n<tr><td>sessionStorage</td><td>탭 단위 격리</td><td>XSS에는 읽힘</td></tr>\n</table>\n<table>\n<tr><th>권장 의사결정</th><th>설명</th></tr>\n<tr><td>장기 refresh token</td><td>브라우저 JS 접근 저장소에 두지 않음. HttpOnly + Secure + SameSite 쿠키와 서버 측 rotation/reuse detection 검토</td></tr>\n<tr><td>access token</td><td>짧은 TTL, 메모리 보관 우선. 새로고침 UX와 refresh 흐름을 함께 설계</td></tr>\n<tr><td>쿠키 방식</td><td>JS가 읽을 수 없어도 XSS가 사용자 권한으로 요청을 보낼 수 있음. CSRF, CSP, 입력 처리와 함께 설계</td></tr>\n<tr><td>logout/revoke</td><td>refresh token 폐기, 세션 목록, 모든 기기 로그아웃 요구를 백엔드와 계약</td></tr>\n</table>\n<div class=\"callout warn\"><span class=\"co-label\">ACCESS TOKEN</span><p>access token은 짧게, refresh token은 회전과 폐기를 설계합니다. 프론트만으로 인증 보안을 완성할 수 없고 백엔드 정책과 함께 설계해야 합니다.</p></div>\n</section>\n\n<section id=\"fesec-ch5\">\n<div class=\"ch-head\"><span class=\"ch-code\">FSEC-05</span><h2>CSP와 보안 헤더</h2></div>\n<p class=\"lede\">CSP는 브라우저가 어떤 리소스를 실행할 수 있는지 제한하는 정책입니다. XSS 피해를 줄이는 강력한 방어층입니다.</p>\n<table>\n<tr><th>헤더</th><th>역할</th></tr>\n<tr><td><code>Content-Security-Policy</code></td><td>script/style/image/connect 출처 제한</td></tr>\n<tr><td><code>X-Content-Type-Options</code></td><td>MIME sniffing 방지</td></tr>\n<tr><td><code>Referrer-Policy</code></td><td>외부 이동 시 referrer 노출 제어</td></tr>\n<tr><td><code>Permissions-Policy</code></td><td>카메라, 위치 등 브라우저 기능 제한</td></tr>\n</table>\n<div class=\"semantic-card answer-card\"><span class=\"sc-label\">CSP 예시 골격</span><br>Content-Security-Policy:<br>default-src 'self';<br>script-src 'self' 'nonce-{REQUEST_NONCE}';<br>style-src 'self' 'nonce-{REQUEST_NONCE}';<br>img-src 'self' data: https:;<br>connect-src 'self' https://api.example.com https://errors.example.com;<br>object-src 'none';<br>base-uri 'self';<br>frame-ancestors 'none'</div>\n<p><code>unsafe-inline</code>은 XSS 방어력을 크게 낮추므로 nonce나 hash 기반으로 inline 실행을 제한합니다. nonce는 요청마다 새로 생성해야 하며, SPA가 호출하는 API, analytics, error monitoring 도메인은 <code>connect-src</code>에 명시합니다.</p>\n<div class=\"semantic-card process-card\"><span class=\"sc-label\">CSP 적용 순서</span><br>\n<p>이 카드는 절차나 구조를 키워드로만 외우지 않고, 실제 작업에서 어떤 판단 순서와 검증 증거를 함께 봐야 하는지 확인하기 위한 실행 맥락입니다. 각 줄은 구현 단계, 실패 가능성, 리뷰 기준을 같이 점검하라는 신호입니다.</p>Report-Only로 먼저 배포<br>위반 로그 수집<br>필요 출처 allowlist 정리<br>inline script 제거 또는 nonce 적용<br>enforce 모드로 전환</div>\n</section>\n\n<section id=\"fesec-ch6\">\n<div class=\"ch-head\"><span class=\"ch-code\">FSEC-06</span><h2>의존성과 공급망</h2></div>\n<p class=\"lede\">프론트엔드는 npm 생태계 위에서 움직입니다. 작은 패키지 하나도 배포 산출물과 사용자 브라우저에 들어갈 수 있습니다.</p>\n<table>\n<tr><th>관리</th><th>기준</th></tr>\n<tr><td>lockfile</td><td>리뷰하고 커밋, 예기치 않은 버전 변경 방지</td></tr>\n<tr><td>dependency audit</td><td>심각도와 실제 reachability를 함께 판단</td></tr>\n<tr><td>package 평가</td><td>유지보수, 다운로드, 권한, 대체 가능성 확인</td></tr>\n<tr><td>bundle 영향</td><td>기능 대비 크기와 transitive dependency 확인</td></tr>\n</table>\n<table>\n<tr><th>운영 정책</th><th>내용</th></tr>\n<tr><td>lockfile diff</td><td>의존성 PR에서 transitive 변경을 리뷰</td></tr>\n<tr><td>package manager 고정</td><td>팀/CI가 같은 install 결과를 얻도록 버전과 설정 고정</td></tr>\n<tr><td>install script 주의</td><td>postinstall 등 실행 script가 있는 패키지는 별도 검토</td></tr>\n<tr><td>dependency confusion</td><td>private scope registry 설정과 패키지 이름 충돌 방지</td></tr>\n<tr><td>자동 업데이트</td><td>Renovate/Dependabot 정책으로 보안 패치와 breaking change를 분리</td></tr>\n</table>\n<table>\n<tr><th>SUPPLY CHAIN RELEASE DECISION</th><th>확인 질문</th><th>실패 신호</th></tr>\n<tr><td>reachability</td><td>취약 패키지가 실제 bundle이나 실행 경로에 포함되는가</td><td>audit severity만 보고 무조건 무시하거나 무조건 배포 중단</td></tr>\n<tr><td>install script</td><td>postinstall/preinstall이 CI나 개발자 머신에서 실행되는가</td><td>새 패키지가 파일 시스템, network, token에 접근하는지 보지 않음</td></tr>\n<tr><td>lockfile drift</td><td>기능 변경 없이 transitive dependency가 대량으로 바뀌었는가</td><td>lockfile을 사람이 리뷰하지 않고 자동 병합</td></tr>\n<tr><td>third-party runtime</td><td>브라우저에서 외부 script가 사용자 세션과 DOM에 접근하는가</td><td>CSP 없이 전역 script를 추가하고 PII 전송 여부를 모름</td></tr>\n</table>\n<div class=\"callout gm\"><span class=\"co-label\">PR CHECK</span><p><code>dangerouslySetInnerHTML</code>, token storage, CSP, 새 third-party script, 인증 redirect, sanitizer 설정 변경은 보안 리뷰 대상으로 표시합니다. 단순 UI 변경처럼 취급하지 않습니다.</p></div>\n<div class=\"glossary\"><div class=\"g-row\"><div class=\"g-term\"><b>SRI</b><span>Subresource Integrity</span></div><div class=\"g-def\">CDN script가 기대한 hash와 일치하는지 브라우저가 검증하는 기능입니다.</div></div><div class=\"g-row\"><div class=\"g-term\"><b>Nonce</b><span>CSP</span></div><div class=\"g-def\">허용된 inline script를 식별하기 위한 요청별 임의값입니다.</div></div></div>\n</section>\n\n<section id=\"fesec-ch7\">\n<div class=\"ch-head\"><span class=\"ch-code\">FSEC-07</span><h2>보안 방법론: 신뢰 경계와 데이터 흐름</h2></div>\n<p class=\"lede\">프론트엔드 보안의 출발점은 “브라우저는 신뢰할 수 없는 실행 환경”이라는 관점입니다. 사용자가 보는 UI는 권한 판단의 근거가 될 수 없고, 클라이언트 상태는 변조 가능하며, 브라우저에 도착한 secret은 이미 노출 가능한 값입니다. 따라서 보안 리뷰는 컴포넌트 이름이 아니라 데이터가 어디서 들어와 어디로 흘러가고 어떤 권한으로 실행되는지를 추적해야 합니다.</p>\n<div class=\"semantic-card decision-card\"><span class=\"sc-label\">BROWSER TRUST BOUNDARY MODEL</span><br>1 untrusted input → 2 parse/normalize → 3 validate/allowlist → 4 encode or sanitize → 5 render/use<br>6 identity signal → 7 session boundary → 8 authorization check → 9 UI affordance<br>10 third-party code → 11 CSP boundary → 12 data exfiltration review → 13 monitoring</div>\n<div class=\"glossary\">\n<div class=\"g-row\"><div class=\"g-term\"><b>1 · 신뢰할 수 없는 입력</b><span>untrusted input</span></div><div class=\"g-def\">URL, 폼, 메시지, 서버 응답까지 바깥에서 온 모든 값. 우리 서버가 준 값도 사용자가 만든 것일 수 있다</div></div>\n<div class=\"g-row\"><div class=\"g-term\"><b>2 · 파싱·정규화</b><span>parse/normalize</span></div><div class=\"g-def\">같은 값의 여러 표기를 하나로 모은다. 정규화 전에 검사하면 우회당한다</div></div>\n<div class=\"g-row\"><div class=\"g-term\"><b>3 · 검증·허용목록</b><span>validate/allowlist</span></div><div class=\"g-def\">허용할 것을 정한다. 금지 목록은 언제나 새는 쪽이다</div></div>\n<div class=\"g-row\"><div class=\"g-term\"><b>4 · 인코딩·새니타이즈</b><span>encode or sanitize</span></div><div class=\"g-def\">쓰는 자리에 맞게 처리한다. HTML, 속성, URL, 스크립트 문맥이 각각 다르다</div></div>\n<div class=\"g-row\"><div class=\"g-term\"><b>5 · 렌더·사용</b><span>render/use</span></div><div class=\"g-def\">여기서 값이 실행 문맥에 들어간다. innerHTML과 링크 href가 대표적인 사고 지점이다</div></div>\n<div class=\"g-row\"><div class=\"g-term\"><b>6 · 신원 신호</b><span>identity signal</span></div><div class=\"g-def\">누가 로그인했는지 알려주는 값. 클라이언트가 들고 있는 것은 표시용이지 근거가 아니다</div></div>\n<div class=\"g-row\"><div class=\"g-term\"><b>7 · 세션 경계</b><span>session boundary</span></div><div class=\"g-def\">쿠키 속성, 만료, 갱신, 로그아웃. 탭·기기 간에 세션이 어떻게 공유되는지까지 포함한다</div></div>\n<div class=\"g-row\"><div class=\"g-term\"><b>8 · 권한 검사</b><span>authorization check</span></div><div class=\"g-def\">서버에서 매 요청 확인한다. 화면이 감췄다는 것은 방어가 아니다</div></div>\n<div class=\"g-row\"><div class=\"g-term\"><b>9 · UI 노출 결정</b><span>UI affordance</span></div><div class=\"g-def\">권한에 따라 보여줄지 비활성할지. 서버 검사와 어긋나지 않게 맞춘다</div></div>\n<div class=\"g-row\"><div class=\"g-term\"><b>10 · 서드파티 코드</b><span>third-party code</span></div><div class=\"g-def\">태그 매니저, 분석, 위젯. 우리 페이지에서 우리 권한으로 돈다는 사실이 핵심이다</div></div>\n<div class=\"g-row\"><div class=\"g-term\"><b>11 · CSP 경계</b><span>CSP boundary</span></div><div class=\"g-def\">무엇을 불러오고 실행할 수 있는지 선언한다. 인라인 스크립트 허용은 대부분의 보호를 무력화한다</div></div>\n<div class=\"g-row\"><div class=\"g-term\"><b>12 · 유출 경로 검토</b><span>data exfiltration review</span></div><div class=\"g-def\">서드파티가 어떤 데이터를 어디로 보내는지 본다. 폼 입력과 URL 파라미터가 새는 통로다</div></div>\n<div class=\"g-row\"><div class=\"g-term\"><b>13 · 모니터링</b><span>monitoring</span></div><div class=\"g-def\">CSP 위반 보고와 오류를 수집한다. 막은 것이 아니라 막히고 있는 것을 보는 단계다</div></div>\n</div>\n<table>\n<tr><th>경계</th><th>핵심 관점</th><th>잘못된 판단</th><th>좋은 증거</th></tr>\n<tr><td>DOM</td><td>HTML, URL, style, markdown은 실행 표면이다</td><td>React라서 XSS가 자동으로 전부 막힌다고 생각</td><td>sanitizer 설정, payload negative test, CSP report</td></tr>\n<tr><td>Session</td><td>토큰 저장은 XSS와 CSRF 사이의 위험 배분이다</td><td>localStorage는 편하고 cookie는 안전하다고 단순화</td><td>token TTL, refresh rotation, SameSite/HttpOnly/Secure, logout/revoke 테스트</td></tr>\n<tr><td>Navigation</td><td>URL은 명령이자 데이터다</td><td>returnTo, redirect_uri, deep link를 문자열로 그대로 신뢰</td><td>origin allowlist, scheme 제한, open redirect negative test</td></tr>\n<tr><td>Third-party</td><td>외부 script는 사용자 세션 안에서 실행되는 코드다</td><td>analytics tag를 비즈니스 설정으로만 취급</td><td>owner, 목적, 전송 데이터, CSP connect/script 출처, 제거 기준</td></tr>\n<tr><td>Client state</td><td>UI 권한 상태는 편의 신호일 뿐 최종 권한이 아니다</td><td>버튼 숨김을 보안 통제로 착각</td><td>서버 401/403 처리, role downgrade, stale session E2E</td></tr>\n</table>\n<h3>DATA FLOW SECURITY REVIEW</h3>\n<p>보안 리뷰는 “위험한 API를 썼는가”보다 “신뢰할 수 없는 값이 위험한 sink까지 검증 없이 도달하는가”를 묻습니다. source는 URL parameter, form input, CMS, API response, postMessage, localStorage, clipboard, uploaded file name입니다. sink는 DOM HTML, href/src/style, fetch URL, analytics payload, redirect, storage, worker message, download filename입니다.</p>\n<table>\n<tr><th>단계</th><th>질문</th><th>산출물</th></tr>\n<tr><td>1. Source 표시</td><td>외부에서 온 값과 사용자 조작 가능 값을 표시했는가</td><td>source/sink map</td></tr>\n<tr><td>2. Trust 변환</td><td>parse, normalize, validate, allowlist가 어느 지점에서 일어나는가</td><td>validation function, schema, allowlist</td></tr>\n<tr><td>3. Sink 확인</td><td>값이 DOM, URL, script, analytics, storage, redirect 중 어디로 가는가</td><td>dangerous sink checklist</td></tr>\n<tr><td>4. Abuse case</td><td>공격자가 어떤 payload와 순서로 오용할 수 있는가</td><td>XSS/open redirect/PII leak negative cases</td></tr>\n<tr><td>5. Regression</td><td>같은 버그가 다시 들어오면 어떤 테스트가 잡는가</td><td>security regression test와 CSP report alert</td></tr>\n</table>\n<h3>AUTH TOKEN DECISION MODEL</h3>\n<p>토큰 저장은 “어디가 안전한가”가 아니라 어떤 공격을 우선 줄이고 어떤 보완 통제를 붙일지의 결정입니다. access token은 짧게, refresh token은 회전과 폐기를 갖게 하고, 브라우저 JS가 장기 secret을 직접 다루지 않게 만드는 쪽이 기본값입니다.</p>\n<table>\n<tr><th>선택</th><th>막는 것</th><th>남는 위험</th><th>필수 보완</th></tr>\n<tr><td>memory access token</td><td>영구 저장소 탈취 창을 줄임</td><td>새로고침, 여러 탭, XSS 실행 요청</td><td>refresh 계약, session restore, CSP, logout</td></tr>\n<tr><td>HttpOnly refresh cookie</td><td>JS가 refresh token을 읽지 못함</td><td>CSRF와 same-site 오해</td><td>SameSite, CSRF token, origin 검증, rotation</td></tr>\n<tr><td>localStorage token</td><td>구현과 복구가 쉬움</td><td>XSS 한 번에 장기 탈취</td><td>강한 CSP, 짧은 TTL, 민감 서비스에서는 재검토</td></tr>\n<tr><td>BFF/session cookie</td><td>토큰을 브라우저 밖으로 숨김</td><td>서버 복잡도, CSRF</td><td>backend session 정책, CSRF, cache-control</td></tr>\n</table>\n<h3>THIRD PARTY SCRIPT GOVERNANCE</h3>\n<p>광고, 분석, 채팅, 결제, A/B 테스트 script는 기능이 아니라 배포 가능한 외부 코드입니다. 추가할 때는 성능 예산, CSP, PII 전송, consent 상태, owner, 제거 조건을 같이 기록합니다. Tag manager는 권한 없는 배포 경로가 될 수 있으므로 변경 승인과 audit log가 필요합니다.</p>\n<div class=\"semantic-card evidence-card\"><span class=\"sc-label\">SECURITY REGRESSION METHOD</span><br>1. 취약 패턴을 source/sink로 재현한다<br>2. payload negative test를 component 또는 E2E에 추가한다<br>3. CSP report-only에서 위반 신호를 확인한다<br>4. analytics/network payload에 PII가 없는지 검사한다<br>5. PR template에 같은 경계 변경 여부를 묻는다</div>\n<div class=\"callout warn\"><span class=\"co-label\">관점</span><p>프론트엔드 보안은 백엔드 보안을 대체하지 않습니다. 다만 사용자의 브라우저 안에서 발생하는 실행, 표시, 이동, 추적, 저장의 위험을 줄이고, 백엔드 권한 실패를 사용자 경험과 관측 신호로 드러나게 만드는 책임을 집니다.</p></div>\n</section>\n\n<section id=\"doc-fetest\">\n<div class=\"ch-head\"><span class=\"ch-code\">SOURCE</span><h2>테스트 전략</h2></div>\n</section>\n\n<section id=\"fetest-ch1\">\n<div class=\"ch-head\"><span class=\"ch-code\">FTEST-01</span><h2>테스트의 목적</h2></div>\n<p class=\"lede\">테스트는 QA 문서가 아니라 변경 안전장치입니다. 실패했을 때 무엇이 깨졌고 사용자에게 어떤 영향이 있는지 알려야 합니다.</p>\n<table>\n<tr><th>나쁜 테스트</th><th>좋은 테스트</th></tr>\n<tr><td>컴포넌트 내부 함수 호출을 검증</td><td>사용자 입력 후 화면 결과를 검증</td></tr>\n<tr><td>거대한 snapshot만 비교</td><td>의미 있는 텍스트, role, 상태를 확인</td></tr>\n<tr><td>mock 구현을 테스트</td><td>실제 DOM과 사용자 이벤트를 테스트</td></tr>\n<tr><td>깨져도 원인을 모름</td><td>테스트 이름이 시나리오와 기대 결과를 말함</td></tr>\n</table>\n</section>\n\n<section id=\"fetest-ch2\">\n<div class=\"ch-head\"><span class=\"ch-code\">FTEST-02</span><h2>테스트 피라미드</h2></div>\n<p class=\"lede\">프론트엔드에서는 피라미드보다 \"테스트 트로피\" 사고가 더 실용적일 때가 많습니다. 순수 로직은 단위, UI 계약은 컴포넌트, 핵심 여정은 E2E로 보호합니다.</p>\n<table>\n<tr><th>층</th><th>대상</th><th>예</th></tr>\n<tr><td>Unit</td><td>순수 함수, reducer, formatter</td><td>가격 포맷, 권한 계산, validation schema</td></tr>\n<tr><td>Component</td><td>DOM과 사용자 상호작용</td><td>필터 입력 후 목록 갱신, 오류 메시지 표시</td></tr>\n<tr><td>Integration</td><td>라우터, 데이터 fetching, provider 조합</td><td>상세 페이지 로딩/실패/성공 상태</td></tr>\n<tr><td>E2E</td><td>핵심 사용자 여정</td><td>로그인 후 생성, 수정, 권한 차단</td></tr>\n</table>\n<table>\n<tr><th>RISK BASED TEST MATRIX</th><th>필수 테스트 조합</th><th>놓치기 쉬운 실패</th></tr>\n<tr><td>권한·인증 변경</td><td>component state + E2E negative path + session expiry case</td><td>로그인 성공만 확인하고 403/401, role downgrade, stale session을 놓침</td></tr>\n<tr><td>폼·제출 변경</td><td>validation unit + component interaction + E2E submit + duplicate click case</td><td>disabled/loading, optimistic UI rollback, 서버 에러 메시지 매핑 누락</td></tr>\n<tr><td>API schema 변경</td><td>MSW fixture update + contract test + runtime error monitoring</td><td>mock은 통과하지만 실제 API nullable/enum 변경으로 contract drift 발생</td></tr>\n<tr><td>라우팅·권한 guard</td><td>router integration + deep link + refresh + back navigation E2E</td><td>직접 URL 진입, 오래된 tab, redirect loop를 놓침</td></tr>\n<tr><td>디자인 시스템 변경</td><td>component + visual regression + a11y smoke + responsive screenshot</td><td>공통 CSS 변경이 긴 텍스트, 모바일, keyboard focus를 깨뜨림</td></tr>\n<tr><td>성능 민감 화면</td><td>interaction test + profiler/trace evidence + bundle diff + Web Vitals watch</td><td>기능은 맞지만 INP/LCP, JS chunk, render fan-out이 악화됨</td></tr>\n</table>\n</section>\n\n<section id=\"fetest-ch3\">\n<div class=\"ch-head\"><span class=\"ch-code\">FTEST-03</span><h2>컴포넌트 테스트</h2></div>\n<p class=\"lede\">Testing Library의 관점은 \"사용자가 찾는 방식으로 찾는다\"입니다. role, label, text를 우선합니다.</p>\n<div class=\"semantic-card process-card\"><span class=\"sc-label\">COMPONENT TEST 원칙</span><br>\n<p>이 카드는 절차나 구조를 키워드로만 외우지 않고, 실제 작업에서 어떤 판단 순서와 검증 증거를 함께 봐야 하는지 확인하기 위한 실행 맥락입니다. 각 줄은 구현 단계, 실패 가능성, 리뷰 기준을 같이 점검하라는 신호입니다.</p>getByRole로 상호작용 요소 찾기<br>userEvent로 실제 입력에 가깝게 조작<br>비동기 UI는 findBy/waitFor 사용<br>내부 state나 private 함수는 직접 검증하지 않음<br>접근 가능한 이름을 테스트가 자연스럽게 요구하게 만들기</div>\n<table>\n<tr><th>Testing Library 규칙</th><th>이유</th></tr>\n<tr><td><code>getByRole({ name })</code> 우선</td><td>사용자와 보조기술이 인식하는 이름을 검증</td></tr>\n<tr><td><code>queryBy*</code>는 부재 검증에 사용</td><td>없는 요소를 찾을 때 throw하지 않음</td></tr>\n<tr><td><code>waitFor</code> 안에 여러 assertion 남발 금지</td><td>실패 원인이 흐려지고 재시도 비용 증가</td></tr>\n<tr><td><code>jest-dom</code> matcher 사용</td><td><code>toBeVisible</code>, <code>toBeDisabled</code>, <code>toHaveAccessibleName</code>처럼 의도를 드러냄</td></tr>\n<tr><td>fake timer와 <code>userEvent</code> 조합 주의</td><td>입력 이벤트와 timer 진행이 어긋나 flaky해질 수 있음</td></tr>\n</table>\n<div class=\"callout\"><span class=\"co-label\">ACCESSIBILITY BENEFIT</span><p>role과 label로 테스트가 가능하다는 것은 보조기술도 그 UI를 이해할 가능성이 높다는 뜻입니다. 테스트 가능성과 접근성은 자주 같은 방향으로 움직입니다.</p></div>\n</section>\n\n<section id=\"fetest-ch4\">\n<div class=\"ch-head\"><span class=\"ch-code\">FTEST-04</span><h2>E2E 테스트</h2></div>\n<p class=\"lede\">E2E는 비싸지만 실제 통합 문제를 잡습니다. 모든 것을 E2E로 덮지 말고, 실패하면 매출/업무 흐름이 깨지는 핵심 경로에 집중합니다.</p>\n<table>\n<tr><th>좋은 후보</th><th>이유</th></tr>\n<tr><td>로그인/로그아웃</td><td>모든 기능의 진입점</td></tr>\n<tr><td>핵심 생성/수정/삭제</td><td>업무 가치가 직접 연결</td></tr>\n<tr><td>결제/신청/제출</td><td>중복 제출과 실패 처리가 중요</td></tr>\n<tr><td>권한별 접근</td><td>보안 회귀 영향이 큼</td></tr>\n</table>\n<table>\n<tr><th>Playwright 규칙</th><th>기준</th></tr>\n<tr><td>locator</td><td><code>getByRole</code>, <code>getByLabel</code>, <code>getByText</code> 우선. <code>data-testid</code>는 안정적인 사용자 식별자가 없을 때만</td></tr>\n<tr><td>대기</td><td><code>page.waitForTimeout</code> 금지. web-first assertion으로 상태를 기다림</td></tr>\n<tr><td>데이터</td><td>테스트별 독립 데이터 생성/정리. 실행 순서에 의존하지 않음</td></tr>\n<tr><td>인증</td><td><code>storageState</code> 재사용은 빠르지만 권한/세션 격리 위험을 고려</td></tr>\n<tr><td>CI artifact</td><td>실패 시 trace, video, screenshot을 남겨 재현 비용을 줄임</td></tr>\n</table>\n<table>\n<tr><th>FLAKY TEST TRIAGE</th><th>증상</th><th>처리</th></tr>\n<tr><td>대기 문제</td><td>로컬은 통과하지만 CI에서 timeout, <code>waitForTimeout</code> 의존</td><td>trace viewer로 실제 상태 전환을 보고 web-first assertion으로 바꾼다</td></tr>\n<tr><td>데이터 오염</td><td>테스트 순서나 병렬 실행 여부에 따라 실패</td><td>테스트별 독립 계정/tenant/data seed를 만들고 cleanup 또는 unique key를 둔다</td></tr>\n<tr><td>네트워크 의존</td><td>외부 API, analytics, feature flag 응답에 따라 흔들림</td><td>핵심 경계는 MSW/route mock으로 통제하고 소수 smoke만 real backend로 둔다</td></tr>\n<tr><td>시간·locale</td><td>날짜, timezone, animation, debounce 때문에 결과가 바뀜</td><td>clock, locale, reduced motion, deterministic fixture를 고정한다</td></tr>\n<tr><td>권한 상태</td><td><code>storageState</code> 재사용 후 세션 만료·role 변경을 놓침</td><td>권한별 state를 분리하고 refresh/expired session 시나리오를 별도 테스트한다</td></tr>\n</table>\n<div class=\"callout warn\"><span class=\"co-label\">FLAKY TEST</span><p>flaky 테스트는 신뢰를 갉아먹습니다. 임의 sleep 대신 명확한 상태를 기다리고, 테스트 데이터는 격리하며, 외부 서비스 의존은 통제합니다.</p></div>\n</section>\n\n<section id=\"fetest-ch5\">\n<div class=\"ch-head\"><span class=\"ch-code\">FTEST-05</span><h2>Mock 전략</h2></div>\n<p class=\"lede\">mock은 빠른 테스트를 만들지만 현실과 멀어질 수 있습니다. 어떤 경계를 mock할지 명확히 정해야 합니다.</p>\n<table>\n<tr><th>방식</th><th>언제</th><th>주의</th></tr>\n<tr><td>함수 mock</td><td>작은 단위 테스트</td><td>구현 세부에 결합되기 쉬움</td></tr>\n<tr><td>MSW</td><td>컴포넌트/통합 테스트에서 API 경계</td><td>실제 API schema와 동기화 필요</td></tr>\n<tr><td>fixture</td><td>반복 데이터</td><td>현실적인 edge case 포함</td></tr>\n<tr><td>real backend</td><td>소수의 smoke/E2E</td><td>데이터 격리와 속도 문제</td></tr>\n</table>\n<table>\n<tr><th>MOCK CONTRACT DRIFT CONTROL</th><th>방어선</th><th>증거</th></tr>\n<tr><td>schema source</td><td>OpenAPI, Zod schema, GraphQL schema 중 하나를 mock fixture의 기준으로 둔다</td><td>fixture generation 또는 schema validation 결과</td></tr>\n<tr><td>enum/nullable</td><td>새 enum, nullable 변경, field 제거가 consumer를 깨는지 검증한다</td><td>contract drift test와 runtime fallback case</td></tr>\n<tr><td>error shape</td><td>성공 응답뿐 아니라 400/401/403/409/500 error contract를 mock한다</td><td>권한·validation·conflict UI 테스트</td></tr>\n<tr><td>latency/failure</td><td>loading, timeout, retry, offline, stale cache를 fixture로 만든다</td><td>spinner, disabled, retry button, toast, rollback UI 검증</td></tr>\n</table>\n</section>\n\n<section id=\"fetest-ch6\">\n<div class=\"ch-head\"><span class=\"ch-code\">FTEST-06</span><h2>시각 회귀</h2></div>\n<p class=\"lede\">프론트엔드는 로직이 맞아도 UI가 깨질 수 있습니다. 시각 회귀는 디자인 시스템과 핵심 화면에 특히 유용합니다.</p>\n<table>\n<tr><th>대상</th><th>왜</th></tr>\n<tr><td>공통 컴포넌트</td><td>작은 변경이 여러 화면에 퍼짐</td></tr>\n<tr><td>핵심 폼</td><td>오류/로딩/비활성 상태 깨짐 방지</td></tr>\n<tr><td>반응형 레이아웃</td><td>모바일에서 겹침/잘림 방지</td></tr>\n<tr><td>차트/테이블</td><td>데이터 길이 변화에 취약</td></tr>\n</table>\n<table>\n<tr><th>VISUAL A11Y RELEASE GATE</th><th>확인 대상</th><th>통과 기준</th></tr>\n<tr><td>keyboard path</td><td>주요 생성/수정/검색/제출 플로우</td><td>Tab, Shift+Tab, Enter, Space, Esc만으로 완료하고 focus trap이 깨지지 않는다</td></tr>\n<tr><td>responsive screenshot</td><td>모바일, 태블릿, 데스크톱 주요 viewport</td><td>텍스트 잘림, 버튼 겹침, table overflow, fixed nav occlusion이 없다</td></tr>\n<tr><td>state coverage</td><td>loading, empty, error, disabled, long text, permission denied</td><td>상태별 화면이 시각 회귀 baseline에 포함된다</td></tr>\n<tr><td>semantic access</td><td>role, label, heading, live region, error message</td><td>자동 a11y 검사와 수동 keyboard walkthrough가 모두 통과한다</td></tr>\n</table>\n<div class=\"glossary\"><div class=\"g-row\"><div class=\"g-term\"><b>Test Contract</b><span>user behavior</span></div><div class=\"g-def\">테스트가 보호하는 사용자 관찰 가능 동작입니다.</div></div><div class=\"g-row\"><div class=\"g-term\"><b>Fixture</b><span>test data</span></div><div class=\"g-def\">테스트에서 반복 사용하는 현실적인 예제 데이터입니다.</div></div></div>\n<div class=\"callout gm\"><span class=\"co-label\">PR CHECK</span><p>새 기능 PR은 어떤 계층의 테스트가 필요한지 명시합니다. 순수 로직은 unit, 사용자 상호작용은 component, 핵심 업무 흐름은 E2E, 공통 UI 변경은 visual regression 후보로 분류합니다.</p></div>\n</section>\n\n<section id=\"fetest-ch7\">\n<div class=\"ch-head\"><span class=\"ch-code\">FTEST-07</span><h2>테스트 방법론: 위험을 가장 싼 위치에서 막기</h2></div>\n<p class=\"lede\">프론트엔드 테스트의 목적은 테스트 개수를 늘리는 것이 아니라 변경 위험을 가장 빠르고 안정적인 계층에서 차단하는 것입니다. 좋은 테스트 전략은 “무엇을 테스트할까”보다 “이 변경이 실패하면 사용자는 어떤 행동을 완료하지 못하고, 그 실패를 어느 계층에서 가장 싸게 잡을 수 있는가”를 먼저 묻습니다.</p>\n<div class=\"semantic-card evidence-card\"><span class=\"sc-label\">TEST STRATEGY AS RISK DESIGN</span><br>1 change risk → 2 user failure mode → 3 cheapest reliable test layer → 4 fixture contract<br>→ 5 CI evidence → 6 release health signal → 7 regression ownership</div>\n<div class=\"glossary\">\n<div class=\"g-row\"><div class=\"g-term\"><b>1 · 변경 위험</b><span>change risk</span></div><div class=\"g-def\">이 변경이 깨지면 무엇을 잃는가. 커버리지가 아니라 위험이 테스트의 출발점이다</div></div>\n<div class=\"g-row\"><div class=\"g-term\"><b>2 · 사용자 실패 모드</b><span>user failure mode</span></div><div class=\"g-def\">사용자에게 어떤 모습으로 실패하는가. 내부 함수가 아니라 이 모습을 고정한다</div></div>\n<div class=\"g-row\"><div class=\"g-term\"><b>3 · 가장 싼 신뢰 층</b><span>cheapest reliable test layer</span></div><div class=\"g-def\">그 실패를 잡을 수 있는 가장 싸고 안정적인 층을 고른다. E2E로 다 덮으려 하면 느리고 잘 깨진다</div></div>\n<div class=\"g-row\"><div class=\"g-term\"><b>4 · 픽스처 계약</b><span>fixture contract</span></div><div class=\"g-def\">테스트가 기대하는 데이터 모양을 고정한다. 실제 응답과 어긋나면 초록불이 거짓말을 한다</div></div>\n<div class=\"g-row\"><div class=\"g-term\"><b>5 · CI 증거</b><span>CI evidence</span></div><div class=\"g-def\">무엇을 검증했는지 PR에서 보이게 남긴다</div></div>\n<div class=\"g-row\"><div class=\"g-term\"><b>6 · 릴리스 건강 신호</b><span>release health signal</span></div><div class=\"g-def\">배포 후 오류율·Web Vitals·핵심 전환을 본다. 테스트가 끝이 아니라 여기까지가 검증이다</div></div>\n<div class=\"g-row\"><div class=\"g-term\"><b>7 · 회귀 소유권</b><span>regression ownership</span></div><div class=\"g-def\">깨진 테스트를 누가 고치는가. 주인 없는 실패는 곧 무시되는 실패가 된다</div></div>\n</div>\n<table>\n<tr><th>위험</th><th>대표 실패</th><th>우선 테스트</th><th>보조 증거</th></tr>\n<tr><td>순수 계산·format</td><td>가격, 날짜, 권한 label이 틀림</td><td>unit</td><td>edge case table</td></tr>\n<tr><td>컴포넌트 상호작용</td><td>loading/error/disabled/focus 상태 누락</td><td>component + Testing Library</td><td>role/label 기반 assertion</td></tr>\n<tr><td>API 계약</td><td>nullable, enum, error shape 변경으로 UI crash</td><td>contract + MSW schema validation</td><td>runtime monitoring</td></tr>\n<tr><td>권한·세션</td><td>403, role downgrade, expired session에서 잘못된 화면</td><td>E2E negative path</td><td>server authorization log</td></tr>\n<tr><td>레이아웃·디자인 시스템</td><td>모바일 겹침, 긴 텍스트 잘림, 회귀</td><td>visual + a11y</td><td>responsive screenshots</td></tr>\n<tr><td>계측</td><td>중복 이벤트, PII 전송, consent 무시</td><td>analytics event test</td><td>network payload capture</td></tr>\n</table>\n<h3>TEST LAYER DECISION TABLE</h3>\n<p>테스트 계층은 선호가 아니라 비용과 신뢰도 선택입니다. unit은 빠르지만 통합을 못 보고, E2E는 신뢰도가 높지만 느리고 흔들릴 수 있습니다. 같은 위험을 unit으로 안정적으로 막을 수 있으면 E2E로 올리지 않고, 사용자 여정이 여러 시스템을 지나야만 드러나는 위험은 E2E로 고정합니다.</p>\n<table>\n<tr><th>질문</th><th>예라면</th><th>아니라면</th></tr>\n<tr><td>DOM 없이 판단 가능한가?</td><td>unit으로 둔다</td><td>component 이상으로 올린다</td></tr>\n<tr><td>사용자 역할, 이름, focus로 관찰 가능한가?</td><td>Testing Library로 보호한다</td><td>구현 세부 테스트를 피하고 UI 계약을 재정의한다</td></tr>\n<tr><td>라우팅, 인증, 브라우저 저장소, 새로고침이 핵심인가?</td><td>Playwright E2E로 둔다</td><td>component/integration에서 더 싸게 막는다</td></tr>\n<tr><td>API shape drift가 위험인가?</td><td>schema 기반 fixture와 contract test를 둔다</td><td>mock만 늘리지 않는다</td></tr>\n<tr><td>픽셀, 반응형, 시각 위계가 실패 지점인가?</td><td>visual regression과 수동 review를 결합한다</td><td>snapshot 남발을 피한다</td></tr>\n</table>\n<h3>PLAYWRIGHT SCENARIO METHOD</h3>\n<p>Playwright 시나리오는 happy path 녹화가 아니라 브라우저 상태 전이를 검증하는 문서입니다. 로그인 성공만 보지 말고 deep link, reload, back navigation, expired session, role downgrade, duplicate submit, network retry, permission denied를 같은 기능의 위험군으로 묶습니다.</p>\n<div class=\"semantic-card evidence-card\"><span class=\"sc-label\">PLAYWRIGHT SCENARIO METHOD</span><br>1. 핵심 사용자 목표를 한 문장으로 쓴다<br>2. 시작 상태를 anonymous/authenticated/expired/forbidden으로 나눈다<br>3. role, route, storageState, network fixture를 명시한다<br>4. 성공 path와 최소 1개 negative path를 같이 둔다<br>5. trace, screenshot, console, network artifact를 실패 증거로 남긴다</div>\n<h3>ANALYTICS EVENT TESTING METHOD</h3>\n<p>계측도 테스트 대상입니다. 이벤트는 클릭 순간이 아니라 의사결정 데이터 계약입니다. trigger, required parameter, identity, consent, PII 제외, 중복 방지, 실패 시 미전송 기준을 테스트해야 합니다.</p>\n<table>\n<tr><th>검증</th><th>방법</th><th>차단 기준</th></tr>\n<tr><td>정확한 trigger</td><td>사용자 행동 후 network payload 또는 dataLayer capture</td><td>렌더링만으로 이벤트 발송</td></tr>\n<tr><td>중복 방지</td><td>double click, retry, route back/forward</td><td>동일 conversion 중복 발송</td></tr>\n<tr><td>privacy</td><td>payload에서 email, phone, free text 검색</td><td>PII 또는 민감 query 포함</td></tr>\n<tr><td>consent</td><td>동의 전/후 상태를 나눠 테스트</td><td>동의 전 광고·분석 cookie 생성</td></tr>\n<tr><td>schema</td><td>event_schema_version과 required params 검사</td><td>dashboard가 깨지는 이름/타입 변경</td></tr>\n</table>\n<h3>TEST FAILURE TRIAGE MODEL</h3>\n<p>실패한 테스트는 고치는 것이 아니라 먼저 분류합니다. 제품 버그, 테스트 버그, fixture drift, 환경 문제, 타이밍 문제, 요구사항 변경을 구분해야 신뢰가 유지됩니다.</p>\n<table>\n<tr><th>분류</th><th>판단 질문</th><th>처리</th></tr>\n<tr><td>제품 버그</td><td>사용자도 같은 실패를 겪는가</td><td>코드를 고치고 회귀 테스트 유지</td></tr>\n<tr><td>테스트 버그</td><td>테스트가 구현 세부나 불안정한 selector에 묶였는가</td><td>role/label/상태 assertion으로 재작성</td></tr>\n<tr><td>fixture drift</td><td>mock이 실제 API와 달라졌는가</td><td>schema source에서 fixture 재생성</td></tr>\n<tr><td>환경 문제</td><td>CI만 실패하고 trace에서 인프라 지연이 보이는가</td><td>격리, retry 정책, 환경 소유자 지정</td></tr>\n<tr><td>요구사항 변경</td><td>새 동작이 의도된 변경인가</td><td>테스트 이름과 기대 동작을 명시적으로 갱신</td></tr>\n</table>\n</section>\n\n<section id=\"doc-fedeploy\">\n<div class=\"ch-head\"><span class=\"ch-code\">SOURCE</span><h2>배포</h2></div>\n</section>\n\n<section id=\"fedeploy-ch1\">\n<div class=\"ch-head\"><span class=\"ch-code\">DEP-01</span><h2>프론트엔드 배포의 본질</h2></div>\n<p class=\"lede\">백엔드는 서버 프로세스를 교체하지만, 프론트엔드는 이미 사용자 브라우저에 내려간 파일과도 공존해야 합니다.</p>\n<table>\n<tr><th>특성</th><th>의미</th><th>위험</th></tr>\n<tr><td>정적 파일</td><td>HTML, JS, CSS, asset을 CDN/서버에서 제공</td><td>캐시된 옛 파일과 새 파일 불일치</td></tr>\n<tr><td>해시 파일명</td><td>내용이 바뀌면 이름이 바뀜</td><td>index.html이 옛 chunk를 가리키면 404</td></tr>\n<tr><td>브라우저 cache</td><td>사용자별로 cache 상태가 다름</td><td>재현 어려운 배포 이슈</td></tr>\n<tr><td>API 계약</td><td>프론트/백엔드가 동시에 바뀌지 않을 수 있음</td><td>호환성 없는 배포 순서</td></tr>\n</table>\n<table>\n<tr><th>FRONTEND DEPLOYMENT HEALTH GATE</th><th>배포 전 확인</th><th>배포 후 확인</th></tr>\n<tr><td>preview deployment</td><td>production build 산출물로 preview URL을 만들고 핵심 route smoke를 실행한다</td><td>preview와 production의 env/config 차이가 릴리스 노트에 남아 있는지 본다</td></tr>\n<tr><td>artifact integrity</td><td>release id, commit SHA, asset hash, sourcemap upload가 서로 매핑된다</td><td>오류 이벤트가 minified stack이 아니라 원본 파일/line으로 복원된다</td></tr>\n<tr><td>cache policy</td><td>index.html은 재검증, hashed asset은 immutable, 이전 asset 보존 기간을 확인한다</td><td>chunk load error와 stale index 비율을 release별로 본다</td></tr>\n<tr><td>quality signal</td><td>test, build, bundle budget, a11y smoke, visual regression gate를 통과한다</td><td>error rate, Web Vitals regression, API failure, user report를 release health window 동안 본다</td></tr>\n</table>\n<div class=\"callout\"><span class=\"co-label\">RULE</span><p>assets는 길게 캐시하고, entry HTML은 짧게 캐시합니다. 해시가 있는 JS/CSS는 immutable하게 둘 수 있지만, index.html은 최신 asset 목록을 받아야 하므로 재검증되어야 합니다.</p></div>\n</section>\n\n<section id=\"fedeploy-ch2\">\n<div class=\"ch-head\"><span class=\"ch-code\">DEP-02</span><h2>Vite build와 환경변수</h2></div>\n<p class=\"lede\">Vite의 환경변수는 빌드 시점에 클라이언트 번들로 주입됩니다. 브라우저에 들어가는 값은 secret이 될 수 없습니다.</p>\n<table>\n<tr><th>항목</th><th>기준</th></tr>\n<tr><td><code>VITE_</code> prefix</td><td>클라이언트에 노출할 변수만 사용</td></tr>\n<tr><td>API base URL</td><td>환경별로 빌드하거나 runtime config 제공</td></tr>\n<tr><td>secret</td><td>프론트 번들에 절대 포함하지 않음</td></tr>\n<tr><td>mode</td><td>development/staging/production 설정 분리</td></tr>\n</table>\n<div class=\"semantic-card process-card\"><span class=\"sc-label\">BUILD OUTPUT</span><br>\n<p>이 카드는 절차나 구조를 키워드로만 외우지 않고, 실제 작업에서 어떤 판단 순서와 검증 증거를 함께 봐야 하는지 확인하기 위한 실행 맥락입니다. 각 줄은 구현 단계, 실패 가능성, 리뷰 기준을 같이 점검하라는 신호입니다.</p>npm run build<br><span class=\"dim\">→</span> dist/index.html<br><span class=\"dim\">→</span> dist/assets/index-[hash].js<br><span class=\"dim\">→</span> dist/assets/index-[hash].css<br><span class=\"dim\">→</span> static assets</div>\n</section>\n\n<section id=\"fedeploy-ch3\">\n<div class=\"ch-head\"><span class=\"ch-code\">DEP-03</span><h2>정적 호스팅·CDN·캐시</h2></div>\n<p class=\"lede\">CDN은 빠르게 전달하지만 잘못된 cache header는 배포 사고를 키웁니다.</p>\n<table>\n<tr><th>파일</th><th>권장 cache</th><th>이유</th></tr>\n<tr><td><code>/assets/*-[hash].js</code></td><td><code>max-age=31536000, immutable</code></td><td>내용 변경 시 파일명이 바뀜</td></tr>\n<tr><td><code>/assets/*-[hash].css</code></td><td><code>max-age=31536000, immutable</code></td><td>내용 변경 시 파일명이 바뀜</td></tr>\n<tr><td><code>/index.html</code></td><td><code>no-cache</code></td><td>최신 asset 목록을 받아야 함</td></tr>\n<tr><td>이미지</td><td>변경 정책에 따라</td><td>파일명 해시 여부 확인</td></tr>\n</table>\n<div class=\"callout warn\"><span class=\"co-label\">SPA FALLBACK</span><p>클라이언트 라우팅을 쓰면 서버는 없는 경로를 404로 끝내지 말고 index.html로 fallback해야 합니다. 단, 실제 asset 경로까지 fallback하면 문제를 숨길 수 있으니 라우팅 경로와 asset 경로를 구분합니다.</p></div>\n<table>\n<tr><th>배포 사고 방어</th><th>기준</th></tr>\n<tr><td>이전 assets 보존</td><td>오래 열린 탭과 stale index가 참조할 수 있으므로 이전 hashed assets를 일정 기간 유지</td></tr>\n<tr><td>CDN purge</td><td>대상은 주로 <code>index.html</code>. hashed asset은 overwrite하지 않고 새 이름으로 배포</td></tr>\n<tr><td>chunk load error</td><td>감지 후 사용자에게 새로고침 UX 제공. 무한 reload 방지</td></tr>\n<tr><td>Service Worker</td><td><code>skipWaiting</code>/<code>clientsClaim</code> 전략과 업데이트 알림 UX를 명시적으로 결정</td></tr>\n<tr><td>API 호환성</td><td>백엔드 API는 최소 한 버전 backward-compatible하게 배포해 프론트/백엔드 순서 차이를 흡수</td></tr>\n</table>\n</section>\n\n<section id=\"fedeploy-ch4\">\n<div class=\"ch-head\"><span class=\"ch-code\">DEP-04</span><h2>sourcemap과 오류 수집</h2></div>\n<p class=\"lede\">운영 오류를 추적하려면 minified stack trace를 원본 코드로 복원할 수 있어야 합니다. sourcemap은 강력하지만 노출 정책을 신중히 정해야 합니다.</p>\n<table>\n<tr><th>전략</th><th>장점</th><th>주의</th></tr>\n<tr><td>비공개 업로드</td><td>오류 수집 도구에서만 복원</td><td>CI에서 release id와 함께 업로드 필요</td></tr>\n<tr><td>공개 sourcemap</td><td>설정 단순</td><td>소스 노출 위험</td></tr>\n<tr><td>sourcemap 없음</td><td>노출 위험 낮음</td><td>운영 디버깅이 매우 어려움</td></tr>\n</table>\n<p>권장 운영 방식은 production sourcemap을 생성하되, Sentry 같은 오류 수집 도구에 release id와 함께 비공개 업로드하고 공개 배포 산출물에서는 <code>.map</code> 파일을 제외하는 것입니다. 빌드 전 secret scan을 수행하고, release artifact와 commit SHA를 매핑해야 stack trace를 배포 이력과 연결할 수 있습니다.</p>\n<div class=\"callout\"><span class=\"co-label\">RELEASE ID</span><p>오류 이벤트에는 release id, commit hash, route, browser, user action context가 함께 있어야 합니다. \"Cannot read property\"만으로는 원인 분석이 어렵습니다.</p></div>\n</section>\n\n<section id=\"fedeploy-ch5\">\n<div class=\"ch-head\"><span class=\"ch-code\">DEP-05</span><h2>rollback과 release</h2></div>\n<p class=\"lede\">좋은 배포는 실패하지 않는 배포가 아니라 실패해도 빠르게 되돌릴 수 있는 배포입니다.</p>\n<table>\n<tr><th>전략</th><th>설명</th></tr>\n<tr><td>atomic deploy</td><td>새 dist를 완성한 뒤 한 번에 current 포인터 전환</td></tr>\n<tr><td>versioned assets</td><td>이전 index가 참조하는 asset도 일정 기간 유지</td></tr>\n<tr><td>feature flag</td><td>코드는 배포하되 노출은 점진적으로 제어</td></tr>\n<tr><td>canary</td><td>일부 사용자/트래픽에 먼저 노출</td></tr>\n</table>\n<table>\n<tr><th>ROLLBACK FORWARD FIX DECISION</th><th>선택 기준</th><th>실행</th></tr>\n<tr><td>feature flag kill switch</td><td>새 기능만 문제이고 기존 경로가 안전하다</td><td>flag off, affected route smoke, 사용자 공지 여부 판단</td></tr>\n<tr><td>rollback</td><td>chunk load error, auth break, blank screen, 결제/제출 불가처럼 핵심 경로가 깨졌다</td><td>이전 index와 asset pointer 복구, CDN purge 범위 제한, release health window 재시작</td></tr>\n<tr><td>forward fix</td><td>영향이 작고 원인이 명확하며 rollback이 더 큰 API/cache 불일치를 만든다</td><td>작은 patch, hotfix test, canary, error rate 비교</td></tr>\n<tr><td>CDN purge</td><td>잘못된 index.html 또는 runtime config가 캐시됐다</td><td>hashed asset 전체 삭제가 아니라 entry/config만 목표로 purge한다</td></tr>\n<tr><td>service worker update</td><td>오프라인 캐시나 SW가 오래된 asset을 붙잡는다</td><td>업데이트 알림, skipWaiting 전략, 무한 새로고침 방지 조건을 확인한다</td></tr>\n</table>\n<div class=\"callout risk\"><span class=\"co-label\">OLD INDEX PROBLEM</span><p>사용자가 오래 열린 탭에서 옛 index가 참조하는 chunk를 요청할 수 있습니다. 배포 직후 이전 assets를 바로 삭제하면 chunk load error가 발생합니다. 이전 assets 보존 기간을 둡니다.</p></div>\n</section>\n\n<section id=\"fedeploy-ch6\">\n<div class=\"ch-head\"><span class=\"ch-code\">DEP-06</span><h2>배포 체크리스트</h2></div>\n<div class=\"glossary\">\n<div class=\"g-row\"><div class=\"g-term\"><b>Build</b><span>before deploy</span></div><div class=\"g-def\">typecheck, test, build가 CI에서 통과해야 합니다.</div></div>\n<div class=\"g-row\"><div class=\"g-term\"><b>Cache</b><span>headers</span></div><div class=\"g-def\">index.html과 hashed assets의 cache policy가 다른지 확인합니다.</div></div>\n<div class=\"g-row\"><div class=\"g-term\"><b>Monitoring</b><span>release</span></div><div class=\"g-def\">배포 후 error rate, Web Vitals, API 실패율을 release별로 봅니다.</div></div>\n<div class=\"g-row\"><div class=\"g-term\"><b>Rollback</b><span>plan</span></div><div class=\"g-def\">이전 dist와 asset을 되돌릴 수 있어야 합니다.</div></div>\n</div>\n<div class=\"semantic-card answer-card\">\n<span class=\"sc-label\">AI NATIVE FRONTEND QUALITY LOOP</span><br>\n1. AI에게 변경 diff를 기준으로 risk label 후보를 만들게 한다<br>\n2. RISK BASED TEST MATRIX에 맞춰 필요한 테스트와 누락된 fixture를 제안하게 한다<br>\n3. 실패한 Playwright trace viewer, screenshot, console log를 요약하게 한다<br>\n4. security review note와 release notes 초안을 만들되 사람이 위험 판단을 확정한다<br>\n5. release health window의 error spike, Web Vitals regression, chunk load error를 요약한다<br>\n6. rollback, feature flag kill switch, forward fix 중 하나의 판단 근거를 남긴다\n</div>\n<div class=\"callout gm\"><span class=\"co-label\">PR CHECK</span><p>배포 관련 변경은 cache header, sourcemap 공개 여부, release id 주입, 이전 assets 보존, rollback 절차, service worker 업데이트 정책을 체크합니다. 한 항목이라도 바뀌면 배포 리허설 또는 staging 검증을 거칩니다.</p></div>\n</section>\n\n<section id=\"fedeploy-ch7\">\n<div class=\"ch-head\"><span class=\"ch-code\">DEP-07</span><h2>릴리스 증거와 피드백 루프</h2></div>\n<p class=\"lede\">고급 프론트엔드 릴리스는 “빌드 성공”으로 끝나지 않습니다. 변경 유형별 회귀 위험을 분류하고, preview에서 증거를 남기고, 배포 후 release health window에서 실제 사용자 지표를 확인한 뒤, 사고가 나면 같은 실패를 막는 테스트와 게이트로 되돌려야 합니다.</p>\n<div class=\"semantic-card evidence-card\"><span class=\"sc-label\">RELEASE EVIDENCE PACKET</span><br>change risk label<br>route and feature impact list<br>test evidence: unit, component, E2E, visual, a11y, contract<br>build evidence: bundle diff, sourcemap upload, asset hash<br>observability evidence: release_id, dashboard link, alert owner<br>rollback evidence: flag, previous artifact, CDN purge scope<br>post-release evidence: error, Web Vitals, API failure, user report window</div>\n<h3>REGRESSION MATRIX BY CHANGE TYPE</h3>\n<table>\n<tr><th>변경 유형</th><th>필수 회귀</th><th>릴리스 차단 조건</th><th>운영 관찰</th></tr>\n<tr><td>Design system/token</td><td>visual, a11y, responsive, long text</td><td>focus ring 손실, contrast 실패, 핵심 화면 overlap</td><td>rage click, support UI 문의, visual diff</td></tr>\n<tr><td>Server state/API</td><td>contract, loading/error/empty, stale cache</td><td>409/422/403 처리 누락, optimistic rollback 없음</td><td>API failure, retry volume, JS error</td></tr>\n<tr><td>Route/rendering</td><td>SSR/hydration, route transition, chunk load</td><td>hydration mismatch, blank screen, chunk 404</td><td>LCP, route latency, chunk error</td></tr>\n<tr><td>Analytics/SEO</td><td>event payload, metadata, schema, consent</td><td>PII 전송, canonical 오류, 이벤트 중복</td><td>event anomaly, Search Console, consent opt-out</td></tr>\n<tr><td>Security</td><td>XSS payload, redirect, token/session, CSP</td><td>untrusted sink, open redirect, token leak</td><td>CSP report, auth error, suspicious redirect</td></tr>\n</table>\n<h3>DESIGN SYSTEM REGRESSION GOVERNANCE</h3>\n<p>디자인 시스템 변경은 작은 CSS 수정이 아니라 제품 전체의 UI 계약 변경입니다. token, primitive, composite component, pattern, page template 중 어디를 바꾸는지 분류하고, 각 층별 소유자와 회귀 범위를 다르게 둡니다.</p>\n<table>\n<tr><th>층</th><th>회귀 범위</th><th>승인 기준</th><th>증거</th></tr>\n<tr><td>Token</td><td>전체 화면 색·간격·타이포그래피</td><td>contrast, density, theme snapshot 통과</td><td>token diff, visual baseline</td></tr>\n<tr><td>Primitive</td><td>Button, Input, Dialog, Menu</td><td>keyboard, focus, disabled/loading/error 상태</td><td>Storybook state matrix, axe result</td></tr>\n<tr><td>Composite</td><td>Table, FilterBar, FormSection</td><td>긴 텍스트, empty/error, permission 상태</td><td>responsive screenshots, E2E smoke</td></tr>\n<tr><td>Pattern</td><td>wizard, bulk action, command palette</td><td>state machine, recovery, telemetry</td><td>scenario trace, event payload capture</td></tr>\n</table>\n<h3>OBSERVABILITY RELEASE GATE</h3>\n<div class=\"semantic-card decision-card\"><span class=\"sc-label\">OBSERVABILITY RELEASE GATE</span><br>release_id is injected into bundle and error events<br>sourcemap upload matches release_id and commit SHA<br>Web Vitals dashboard is filtered by route and release<br>API spans carry request id or normalized endpoint<br>analytics events include schema version and consent state<br>alert owner and rollback decision window are documented</div>\n<h3>INCIDENT FEEDBACK LOOP</h3>\n<p>프론트엔드 사고의 후속 조치는 hotfix로 끝나면 안 됩니다. 원인을 회귀 테스트, 릴리스 게이트, 관측 신호, 디자인 시스템 정책 중 하나 이상으로 되돌려야 같은 사고가 반복되지 않습니다.</p>\n<div class=\"semantic-card answer-card\"><span class=\"sc-label\">INCIDENT FEEDBACK LOOP</span><br>1 incident symptom → 2 affected route and release<br>→ 3 user impact and rollback decision<br>→ 4 root cause category: state, API, render, cache, security, design system<br>→ 5 missing test or missing signal<br>→ 6 new regression case<br>→ 7 release gate update<br>→ 8 owner and review date</div>\n<div class=\"glossary\">\n<div class=\"g-row\"><div class=\"g-term\"><b>1 · 장애 증상</b><span>incident symptom</span></div><div class=\"g-def\">사용자가 겪은 것을 그대로 적는다. 원인 추정을 증상 자리에 쓰지 않는다</div></div>\n<div class=\"g-row\"><div class=\"g-term\"><b>2 · 영향 라우트·릴리스</b><span>affected route and release</span></div><div class=\"g-def\">어느 화면이 어느 배포부터 깨졌는가. 시간축을 배포와 맞춘다</div></div>\n<div class=\"g-row\"><div class=\"g-term\"><b>3 · 영향과 롤백 판단</b><span>user impact and rollback</span></div><div class=\"g-def\">얼마나 많은 사용자가 무엇을 못 하는가. 원인을 모르더라도 되돌릴지 여기서 정한다</div></div>\n<div class=\"g-row\"><div class=\"g-term\"><b>4 · 원인 범주</b><span>root cause category</span></div><div class=\"g-def\">상태, API, 렌더, 캐시, 보안, 디자인 시스템 중 어디인가. 범주가 다음에 볼 곳을 정한다</div></div>\n<div class=\"g-row\"><div class=\"g-term\"><b>5 · 빠진 테스트·신호</b><span>missing test or signal</span></div><div class=\"g-def\">왜 미리 못 잡았는가. 테스트가 없었는지, 지표가 없었는지를 구분한다</div></div>\n<div class=\"g-row\"><div class=\"g-term\"><b>6 · 회귀 케이스 추가</b><span>new regression case</span></div><div class=\"g-def\">이 사고를 재현하는 테스트를 남긴다. 여기까지 해야 같은 장애가 반복되지 않는다</div></div>\n<div class=\"g-row\"><div class=\"g-term\"><b>7 · 릴리스 게이트 갱신</b><span>release gate update</span></div><div class=\"g-def\">배포 전에 무엇을 더 확인할지 절차에 반영한다</div></div>\n<div class=\"g-row\"><div class=\"g-term\"><b>8 · 담당자와 점검일</b><span>owner and review date</span></div><div class=\"g-def\">누가 언제까지 확인하는가. 날짜 없는 후속 조치는 닫히지 않는다</div></div>\n</div>\n</section>",
};

export default document;
